                    )
                }
            }
            if event == .sheetDropRow {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [],
                        transitionIndex: 7,
                        hasActions: true,
                        isInternal: true
                    )
                }
            }
            if event == .sheetGone {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [],
                        transitionIndex: 8,
                        hasActions: true,
                        isInternal: true
                    )
                }
            }
            if event == .sheetAddCol {
                do {
                    return EnabledTransition(
                        source: state,
